import { Check } from "lucide-react";

interface PricingHeaderProps {
  billingCycle: "monthly" | "yearly";
  setBillingCycle: (cycle: "monthly" | "yearly") => void;
}

export default function PricingHeader({ billingCycle, setBillingCycle }: PricingHeaderProps) {
  return (
    <div className="mb-16">
      {/* Main Heading */}
      <h1 className="text-center text-6xl font-bold text-gray-900 mb-12 leading-tight">
        The best work <span className="text-gray-500">solution,</span>
        <br />
        <span className="text-gray-500">for the best price.</span>
      </h1>

      {/* Bottom Section with Guarantee and Toggle */}
      <div className="flex items-center justify-between max-w-7xl mx-auto">
        {/* Money-back Guarantee - Left Side */}
        <div className="flex items-center gap-2">
          <Check className="text-green-600" size={20} />
          <span className="text-gray-700 font-medium">100% Money-back Guarantee</span>
        </div>

        {/* Billing Toggle - Right Side */}
        <div className="flex items-center gap-4">
          <span className="text-sm text-blue-600 font-medium">Save up to 30% with yearly</span>
          <div className="inline-flex rounded-lg border border-gray-300 bg-white p-1 shadow-sm">
            <button
              onClick={() => setBillingCycle("monthly")}
              className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${
                billingCycle === "monthly"
                  ? "bg-gray-100 text-gray-900 shadow-sm"
                  : "text-gray-600 hover:text-gray-900"
              }`}
            >
              Monthly
            </button>
            <button
              onClick={() => setBillingCycle("yearly")}
              className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${
                billingCycle === "yearly"
                  ? "bg-gray-100 text-gray-900 shadow-sm"
                  : "text-gray-600 hover:text-gray-900"
              }`}
            >
              Yearly
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}